create table if not exists public.game_profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text not null default 'Unknown',best_time integer,created_at timestamptz default now());alter table public.game_profiles enable row level security;create policy "read profiles" on public.game_profiles for select to authenticated using(true);create policy "own profile" on public.game_profiles for insert to authenticated with check((select auth.uid())=id);create table if not exists public.game_runs(id bigint generated always as identity primary key,user_id uuid references auth.users(id) on delete cascade,room_code text,result text not null,seconds integer,created_at timestamptz default now());alter table public.game_runs enable row level security;create policy "own runs" on public.game_runs for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);